#!/usr/bin/env python3
"""Print-ready large-print Sudoku book. Standard 9x9 puzzles, generated by
applying random symmetry-preserving transformations to a base solved grid and
then removing cells per difficulty level. Defaults to 100 puzzles at mixed
difficulty (40 easy, 35 medium, 25 hard), one per page, solutions at the back."""
from __future__ import annotations
import argparse, json, os, random
from reportlab.pdfgen import canvas
from reportlab.pdfgen.canvas import Canvas
from reportlab.lib.pagesizes import letter

PAGE_W, PAGE_H = letter
MARGIN = 54

SudokuGrid = list[list[int]]

from font_utils import pdf_font_candidates, register_pdf_font
from publishing.title_pages import render_title_page, spec_from_mapping

PDF_FONT_FAMILIES = {
    "Sans":  "sans",
    "SansB": "sans-bold",
    "MonoB": "mono-bold",
}


def register_fonts() -> None:
    unresolved = [
        alias for alias, family in PDF_FONT_FAMILIES.items()
        if not register_pdf_font(alias, pdf_font_candidates(family))
    ]
    if unresolved:
        raise RuntimeError(
            f"Required font(s) could not be found for: {', '.join(unresolved)}. "
            "Install or restore the standard Arial and Courier New fonts, then try again."
        )


# ---------------- Sudoku grid generation ----------------
BASE = [
    [1, 2, 3, 4, 5, 6, 7, 8, 9],
    [4, 5, 6, 7, 8, 9, 1, 2, 3],
    [7, 8, 9, 1, 2, 3, 4, 5, 6],
    [2, 3, 4, 5, 6, 7, 8, 9, 1],
    [5, 6, 7, 8, 9, 1, 2, 3, 4],
    [8, 9, 1, 2, 3, 4, 5, 6, 7],
    [3, 4, 5, 6, 7, 8, 9, 1, 2],
    [6, 7, 8, 9, 1, 2, 3, 4, 5],
    [9, 1, 2, 3, 4, 5, 6, 7, 8],
]


def make_solved(rng: random.Random) -> SudokuGrid:
    """Apply random symmetry-preserving transforms to BASE; result is a fresh valid Sudoku solution."""
    g = [row[:] for row in BASE]

    # Permute digits 1-9
    perm = list(range(1, 10))
    rng.shuffle(perm)
    g = [[perm[v - 1] for v in row] for row in g]

    # Swap rows within each band (3 bands of 3 rows each)
    for band in range(3):
        rows = [band * 3 + i for i in range(3)]
        rng.shuffle(rows)
        new_rows = [g[r] for r in rows]
        for i in range(3):
            g[band * 3 + i] = new_rows[i]

    # Swap columns within each stack (3 stacks of 3 cols each)
    for stack in range(3):
        cols = [stack * 3 + i for i in range(3)]
        rng.shuffle(cols)
        for r in range(9):
            row = g[r]
            new_vals = [row[c] for c in cols]
            for i in range(3):
                g[r][stack * 3 + i] = new_vals[i]

    # Swap bands (the 3 row-bands as a whole)
    bands = [0, 1, 2]
    rng.shuffle(bands)
    new_g = []
    for b in bands:
        new_g.extend(g[b * 3:(b + 1) * 3])
    g = new_g

    # Swap stacks (the 3 col-stacks as a whole)
    stacks = [0, 1, 2]
    rng.shuffle(stacks)
    for r in range(9):
        row = g[r]
        new_row = []
        for s in stacks:
            new_row.extend(row[s * 3:(s + 1) * 3])
        g[r] = new_row

    # Optional transpose (50% chance) — rows<->cols, still valid Sudoku
    if rng.random() < 0.5:
        g = [[g[c][r] for c in range(9)] for r in range(9)]

    return g


ALL_BITS = 0b1111111110  # bits for digits 1..9 (bit 0 unused)


def count_solutions(grid: SudokuGrid, limit: int = 2) -> int:
    """Count solutions (capped at `limit`) of a 9x9 grid (0 = empty) via MRV backtracking.
    Returns as soon as `limit` is reached. Used to GUARANTEE puzzle uniqueness."""
    rows = [0] * 9
    cols = [0] * 9
    boxes = [0] * 9
    for r in range(9):
        for c in range(9):
            v = grid[r][c]
            if v:
                b = 1 << v
                rows[r] |= b; cols[c] |= b; boxes[(r // 3) * 3 + c // 3] |= b

    cnt = 0

    def solve() -> None:
        nonlocal cnt
        # pick the empty cell with the fewest candidates (MRV) for speed
        best: tuple[int, int] | None = None
        best_cands = 0
        best_n = 99
        for r in range(9):
            for c in range(9):
                if grid[r][c] == 0:
                    used = rows[r] | cols[c] | boxes[(r // 3) * 3 + c // 3]
                    cand = ALL_BITS & ~used
                    n = bin(cand).count("1")
                    if n == 0:
                        return            # dead end, no solution down this branch
                    if n < best_n:
                        best_n = n; best = (r, c); best_cands = cand
                        if n == 1:
                            break
            if best_n == 1:
                break
        if best is None:
            cnt += 1                       # all cells filled -> one full solution
            return
        r, c = best
        bi = (r // 3) * 3 + c // 3
        for v in range(1, 10):
            bit = 1 << v
            if best_cands & bit:
                grid[r][c] = v; rows[r] |= bit; cols[c] |= bit; boxes[bi] |= bit
                solve()
                grid[r][c] = 0; rows[r] &= ~bit; cols[c] &= ~bit; boxes[bi] &= ~bit
                if cnt >= limit:
                    return

    solve()
    return cnt


def make_puzzle(solved: SudokuGrid, difficulty: str, rng: random.Random) -> SudokuGrid:
    """Carve a puzzle from a solved grid while GUARANTEEING a unique solution.
    A cell is only blanked if the puzzle still has exactly one solution afterward,
    so the printed `solved` grid is always THE answer. Difficulty caps how many
    blanks we aim for (easy=40, medium=48, hard=54); uniqueness may stop us short."""
    target_blanks = {"easy": 40, "medium": 48, "hard": 54}.get(difficulty, 48)
    puzzle = [row[:] for row in solved]
    coords = [(r, c) for r in range(9) for c in range(9)]
    rng.shuffle(coords)
    blanks = 0
    for r, c in coords:
        if blanks >= target_blanks:
            break
        if puzzle[r][c] == 0:
            continue
        saved = puzzle[r][c]
        puzzle[r][c] = 0
        # keep the blank only if the solution is still unique; otherwise put it back
        if count_solutions([row[:] for row in puzzle], limit=2) == 1:
            blanks += 1
        else:
            puzzle[r][c] = saved
    return puzzle


# ---------------- PDF rendering ----------------
def make_rated_puzzle(solved: SudokuGrid, difficulty: str, rng: random.Random, max_attempts: int = 150):
    """Generate to the requested human-technique band without relabelling a miss."""
    from publishing.sudoku_difficulty import rate_sudoku
    if difficulty not in {'easy','medium','hard'}:
        raise ValueError('Choose easy, medium, or hard Sudoku.')
    for _ in range(max_attempts):
        # Medium requires enough open cells for pairs/locked candidates to matter.
        puzzle = make_puzzle(solved,'easy' if difficulty=='easy' else 'hard',rng)
        rating = rate_sudoku(puzzle)
        if rating['label']==difficulty:
            return puzzle,rating
    raise ValueError(f'Could not generate a technique-rated {difficulty} Sudoku after {max_attempts} attempts.')


def _draw_shape(c: Canvas, value: int, cx: float, cy: float, size: float, symbol_pack: str = "classic") -> None:
    from sudoku_symbols import draw_symbol
    draw_symbol(c, symbol_pack, value, cx, cy, size)


def draw_sudoku(c: Canvas, grid: SudokuGrid, gx: float, gy_top: float, cell: float,
                 number_font: str, number_size: float,
                 solution_overlay: SudokuGrid | None = None, display_style: str = "numbers",
                 symbol_pack: str = "classic", region_role: str | None = None) -> None:
    """Render a 9x9 Sudoku grid. gy_top is the top y-coordinate.
    solution_overlay (optional): grayed-in numbers showing the answers for cells the puzzle had blank."""
    if region_role not in (None, 'puzzle', 'solution'):
        raise ValueError('Sudoku text region role must be puzzle or solution.')
    size = 9 * cell
    regions = getattr(c,'_puzzle_text_regions',[])
    regions.append(dict(page=c.getPageNumber(),role=region_role if region_role is not None else ('solution' if number_size<20 else 'puzzle'),
                        bounds=[gx,gy_top-size,gx+size,gy_top],font_pt=number_size))
    c._puzzle_text_regions = regions

    # white background
    c.setFillColorRGB(1, 1, 1)
    c.rect(gx, gy_top - size, size, size, stroke=0, fill=1)

    # thin gridlines (every cell)
    # KDP's print guidance calls for lines that remain visible after printing.
    c.setLineWidth(0.8)
    c.setStrokeColorRGB(0.65, 0.65, 0.65)
    for i in range(10):
        c.line(gx + i * cell, gy_top, gx + i * cell, gy_top - size)
        c.line(gx, gy_top - i * cell, gx + size, gy_top - i * cell)

    # heavy 3x3 box lines
    c.setLineWidth(2.4)
    c.setStrokeColorRGB(0.1, 0.1, 0.1)
    for i in (0, 3, 6, 9):
        c.line(gx + i * cell, gy_top, gx + i * cell, gy_top - size)
        c.line(gx, gy_top - i * cell, gx + size, gy_top - i * cell)

    # Numbers, letters, or font-free vector shapes use the same verified grid.
    c.setFont(number_font, number_size)
    for r in range(9):
        for col in range(9):
            v = grid[r][col]
            if v != 0:
                c.setFillColorRGB(0, 0, 0)
                cx = gx + col * cell + cell / 2
                cy = gy_top - r * cell - cell / 2 - number_size * 0.34
                if display_style == "letters": c.drawCentredString(cx, cy, chr(64 + v))
                elif display_style == "shapes": _draw_shape(c, v, cx, cy + number_size * .18, cell, symbol_pack)
                else: c.drawCentredString(cx, cy, str(v))

    # solution overlay (the values that were originally blank, drawn lighter)
    if solution_overlay is not None:
        c.setFillColorRGB(0.55, 0.45, 0.05)
        c.setFont(number_font, number_size)
        for r in range(9):
            for col in range(9):
                if grid[r][col] == 0 and solution_overlay[r][col] != 0:
                    cx = gx + col * cell + cell / 2
                    cy = gy_top - r * cell - cell / 2 - number_size * 0.34
                    v = solution_overlay[r][col]
                    if display_style == "letters": c.drawCentredString(cx, cy, chr(64 + v))
                    elif display_style == "shapes": _draw_shape(c, v, cx, cy + number_size * .18, cell, symbol_pack)
                    else: c.drawCentredString(cx, cy, str(v))


def footer(c: Canvas, page_no: int) -> None:
    c.setFillColorRGB(0.45, 0.45, 0.45)
    c.setFont("Sans", 9)
    c.drawCentredString(PAGE_W / 2, 34, str(page_no))


def front_matter(c: Canvas, title: str, subtitle: str, author: str) -> None:
    metadata = {"title": title, "subtitle": subtitle, "author": author, "puzzle_type": "Sudoku"}
    render_title_page(c, spec_from_mapping(metadata, puzzle_type="Sudoku"), page_size=(PAGE_W, PAGE_H))

    c.setFillColorRGB(0.2, 0.2, 0.2); c.setFont("Sans", 10)
    cr_lines = [
        f"Copyright © 2026 {author}. All rights reserved.",
        "",
        "No part of this publication may be reproduced, distributed, or transmitted",
        "in any form without the prior written permission of the publisher,",
        "except for brief quotations in reviews.",
        "",
        "The puzzles in this book are an original compilation.",
    ]
    for i, ln in enumerate(cr_lines):
        c.drawString(MARGIN, PAGE_H - 120 - i * 16, ln)
    c.showPage()

    c.setFillColorRGB(0.1, 0.1, 0.1); c.setFont("SansB", 22)
    c.drawCentredString(PAGE_W / 2, PAGE_H - 140, "HOW TO PLAY SUDOKU")
    c.setFont("Sans", 13)
    how = [
        "Fill the grid so every row, every column,",
        "and every 3 × 3 box contains the digits 1 through 9.",
        "",
        "No row, column, or box may repeat a digit.",
        "",
        "Use logic, never guessing — each puzzle has just one solution.",
        "",
        "Stuck? Full solutions are at the back of the book.",
        "",
        "Take your time. There is no clock. Enjoy the quiet.",
    ]
    for i, ln in enumerate(how):
        c.drawCentredString(PAGE_W / 2, PAGE_H - 200 - i * 24, ln)
    c.showPage()


def puzzle_page(c: Canvas, idx: int, difficulty: str, puzzle: SudokuGrid,
                 page_no: int, running: str, display_style: str = "numbers") -> None:
    from publishing.sudoku_difficulty import rate_sudoku
    difficulty = rate_sudoku(puzzle)['label']
    c.setFillColorRGB(0.5, 0.5, 0.5); c.setFont("Sans", 10)
    c.drawCentredString(PAGE_W / 2, PAGE_H - 40, running)
    c.setFillColorRGB(0.1, 0.1, 0.1); c.setFont("SansB", 12)
    c.drawString(MARGIN, PAGE_H - 64, f"PUZZLE {idx}")
    c.setFont("SansB", 11)
    c.setFillColorRGB(0.4, 0.4, 0.4)
    label = {"numbers": "NUMBER", "letters": "LETTER", "shapes": "SHAPE"}.get(display_style, "NUMBER")
    c.drawRightString(PAGE_W - MARGIN, PAGE_H - 64, f"{label} • {difficulty.upper()}")

    cell = 50
    grid_w = 9 * cell
    gx = (PAGE_W - grid_w) / 2
    gy_top = PAGE_H - 130
    draw_sudoku(c, puzzle, gx, gy_top, cell, "MonoB", 28, display_style=display_style, region_role="puzzle")

    footer(c, page_no)
    c.showPage()


def solutions_section(c: Canvas, items: list[tuple[int, SudokuGrid, SudokuGrid, str]],
                       page_no_start: int, running: str) -> int:
    """6 mini-grids per page (2x3 layout) — compact solutions."""
    page_no = page_no_start
    c.setFillColorRGB(0.1, 0.1, 0.1); c.setFont("SansB", 30)
    c.drawCentredString(PAGE_W / 2, PAGE_H / 2 + 10, "SOLUTIONS")
    footer(c, page_no); c.showPage(); page_no += 1

    cell = 18  # solutions: smaller cells so 3 rows (6/page) fit within the bottom margin on 8.5x11
    grid_w = 9 * cell
    cols = 2
    col_gap = 40
    row_gap = 40
    total_w = cols * grid_w + (cols - 1) * col_gap
    start_x = (PAGE_W - total_w) / 2

    per_page = 6
    for i in range(0, len(items), per_page):
        c.setFillColorRGB(0.5, 0.5, 0.5); c.setFont("Sans", 10)
        c.drawCentredString(PAGE_W / 2, PAGE_H - 40, running)
        batch = items[i:i + per_page]
        for j, (idx, puzzle, solved, display_style) in enumerate(batch):
            row, col = divmod(j, cols)
            gx = start_x + col * (grid_w + col_gap)
            top_y = PAGE_H - 90 - row * (grid_w + row_gap + 30)
            c.setFillColorRGB(0.1, 0.1, 0.1); c.setFont("SansB", 11)
            c.drawCentredString(gx + grid_w / 2, top_y + 10, f"PUZZLE {idx}")
            draw_sudoku(c, solved, gx, top_y, cell, "MonoB", 13, display_style=display_style, region_role="solution")
        footer(c, page_no); c.showPage(); page_no += 1
    return page_no


def back_matter(c: Canvas, author: str, also_from: list[dict]) -> None:
    """Same back matter pattern as wordsearch.py: review CTA + cross-sell + about."""
    import math as _m
    c.setFillColorRGB(0.1, 0.1, 0.1); c.setFont("SansB", 28)
    c.drawCentredString(PAGE_W / 2, PAGE_H - 200, "DID YOU ENJOY THIS BOOK?")
    c.setFont("Sans", 14)
    lines = [
        "",
        "Reviews are how small publishers like us reach more readers.",
        "If you enjoyed these puzzles, please leave a quick review on Amazon.",
        "",
        "Even one honest sentence makes a real difference.",
        "",
        f"Thank you, from everyone at {author}.",
    ]
    for i, ln in enumerate(lines):
        c.drawCentredString(PAGE_W / 2, PAGE_H - 260 - i * 24, ln)
    c.setStrokeColorRGB(0.5, 0.55, 0.5); c.setLineWidth(1)
    c.line(PAGE_W / 2 - 80, PAGE_H - 470, PAGE_W / 2 + 80, PAGE_H - 470)
    # 5 yellow stars as polygons (font-free)
    c.setFillColorRGB(0.95, 0.78, 0.12); c.setStrokeColorRGB(0.7, 0.55, 0.08); c.setLineWidth(0.75)
    star_y = PAGE_H - 510
    spacing = 32
    R = 11
    start_x = PAGE_W / 2 - spacing * 4 / 2
    for i in range(5):
        cx = start_x + i * spacing
        pts = []
        for k in range(10):
            ang = -_m.pi / 2 + k * _m.pi / 5
            r = R if k % 2 == 0 else R * 0.45
            pts.append((cx + r * _m.cos(ang), star_y + r * _m.sin(ang)))
        p = c.beginPath()
        p.moveTo(*pts[0])
        for pt in pts[1:]:
            p.lineTo(*pt)
        p.close()
        c.drawPath(p, stroke=1, fill=1)
    c.showPage()

    if also_from:
        c.setFillColorRGB(0.1, 0.1, 0.1); c.setFont("SansB", 26)
        c.drawCentredString(PAGE_W / 2, PAGE_H - 180, f"ALSO FROM {author.upper()}")
        c.setStrokeColorRGB(0.5, 0.55, 0.5)
        c.line(PAGE_W / 2 - 80, PAGE_H - 200, PAGE_W / 2 + 80, PAGE_H - 200)
        c.setFont("Sans", 13)
        c.drawCentredString(PAGE_W / 2, PAGE_H - 230,
                            "Search the titles below on Amazon to find them:")
        y = PAGE_H - 290
        for entry in also_from:
            c.setFont("SansB", 14)
            c.drawCentredString(PAGE_W / 2, y, entry.get("title", ""))
            sub = entry.get("subtitle", "")
            if sub:
                c.setFont("Sans", 11); c.setFillColorRGB(0.4, 0.4, 0.4)
                c.drawCentredString(PAGE_W / 2, y - 18, sub)
                c.setFillColorRGB(0.1, 0.1, 0.1)
            y -= 64
        c.showPage()


def _wrap(text: str, width: int) -> list[str]:
    words = text.split()
    lines: list[str] = []
    cur = ""
    for w in words:
        if len(cur) + len(w) + 1 <= width:
            cur = (cur + " " + w).strip()
        else:
            lines.append(cur); cur = w
    if cur: lines.append(cur)
    return lines or [text]


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--title", default="Large Print Sudoku")
    ap.add_argument("--subtitle", default="100 Number, Letter and Shape Sudoku Puzzles with Full Solutions")
    ap.add_argument("--author", default="Evergreen Puzzle Press")
    ap.add_argument("--count", type=int, default=100)
    ap.add_argument("--also-from", default="")  # path to JSON list
    ap.add_argument("--out", required=True)
    ap.add_argument("--seed", type=int, default=11)
    ap.add_argument("--profile", default="mixed", choices=["easy", "mixed", "hard"])
    a = ap.parse_args()

    rng = random.Random(a.seed)
    register_fonts()

    # Build the puzzles (difficulty mix depends on profile -> genuinely distinct books)
    ratios = {"easy": (0.70, 0.30, 0.0), "mixed": (0.40, 0.35, 0.25), "hard": (0.0, 0.40, 0.60)}[a.profile]
    ne = int(a.count * ratios[0]); nm = int(a.count * ratios[1])
    difficulties = ["easy"] * ne + ["medium"] * nm + ["hard"] * (a.count - ne - nm)
    rng.shuffle(difficulties)  # mix them through the book

    puzzles = []
    special_styles = ("numbers", "letters", "shapes")
    for idx, d in enumerate(difficulties):
        solved = make_solved(rng)
        puzzle, rating = make_rated_puzzle(solved, d, rng)
        from publishing.sudoku_difficulty import rate_sudoku
        puzzles.append((rate_sudoku(puzzle)['label'], puzzle, solved, special_styles[idx % len(special_styles)]))

    also_from = []
    if a.also_from and os.path.exists(a.also_from):
        also_from = json.load(open(a.also_from))

    os.makedirs(os.path.dirname(a.out) or ".", exist_ok=True)
    c = canvas.Canvas(a.out, pagesize=letter)
    c.setTitle(a.title); c.setAuthor(a.author)

    front_matter(c, a.title, a.subtitle, a.author)

    page_no = 1
    items_for_sol = []
    records = []
    for i, (d, p, s, display_style) in enumerate(puzzles, start=1):
        records.append(dict(number=i, type='sudoku', grid=p, solution_grid=s,
                            puzzle_page=c.getPageNumber(), display_style=display_style,
                            difficulty=rate_sudoku(p)))
        puzzle_page(c, i, d, p, page_no, a.title, display_style)
        items_for_sol.append((i, p, s, display_style))
        page_no += 1

    solution_start = c.getPageNumber() + 1
    page_no = solutions_section(c, items_for_sol, page_no, a.title)
    for index, record in enumerate(records):
        record['solution_page'] = solution_start + index // 6

    back_matter(c, a.author, also_from)

    c.save()
    from publishing.puzzle_integrity import write_manifest
    write_manifest(a.out, records, getattr(c,'_puzzle_text_regions',[]))

    size_kb = os.path.getsize(a.out) / 1024
    print(f"DONE -> {a.out}")
    measured = [row[0] for row in puzzles]
    print(f"  {a.count} Sudoku puzzles ({measured.count('easy')} easy / {measured.count('medium')} medium / {measured.count('hard')} hard; technique-rated) + solutions, {size_kb:.0f} KB")


if __name__ == "__main__":
    main()
